<?php namespace Workspace; $b=$botsBinding; $m=$botsMessage; ?>
<section class="panel"><h2>Доставка сообщений CajeerBots</h2><p>Подтвердите точный текст и канал перед постановкой в очередь. Сетевой сбой после начала передачи не является подтверждением недоставки.</p><form method="get" class="inline"><input type="hidden" name="p" value="bots"><label>Проект<select name="project" required><?php selectOptions($botsProjects,$botsProject) ?></select></label><button class="secondary">Открыть</button></form></section>
<?php if($botsProject!==null): ?>
<?php if($botsOwner): ?><section class="panel"><h2>Привязка</h2><?php if($botsCandidate): ?><p>Выбранная оператором цель: <strong><?= h($botsCandidate['provider']) ?> · <?= h($botsCandidate['channel_id']) ?></strong> · <?= h($botsCandidate['origin']) ?> · сообщество <?= h($botsCandidate['community_id']) ?> · аккаунт <?= h($botsCandidate['account_id']) ?></p><?php else: ?><p>Нет доступной конфигурации для активации. Действующую привязку можно отключить.</p><?php endif ?><p>Цель и выделенный ключ задаются оператором в защищённом файле. Отключение запрещает новые передачи в Bots, но не отменяет уже принятые сообщения.</p><form method="post" class="inline"><?php formFields('bots.binding') ?><input type="hidden" name="identity_hash" value="<?= h($botsCandidate['identity_hash']??'') ?>"><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><label>Состояние<select name="active"><?php selectOptions(['1'=>'Включить','0'=>'Отключить'],(string)($b['active']??1)) ?></select></label><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю назначение канала</label><button class="primary">Сохранить (MFA)</button></form></section><?php endif ?>
<?php if(!$b): ?><section class="panel"><p>Нет подключённого канала.</p></section><?php else: ?>
<section class="panel"><h2>Разрешённый канал</h2><p>Поддерживаемая база: CajeerBots <?= h(BOTS_UPSTREAM_VERSION) ?> с обязательным патчем, <code><?= h(BOTS_UPSTREAM_COMMIT) ?></code>; протокол <?= h(BOTS_DELIVERY_API) ?>. Версия upstream не возвращается API; соответствие сборки подтверждает оператор.</p><p><?= h($b['provider']) ?> · <?= (int)$b['active']?'активен':'отключён' ?> · <code><?= h($b['origin']) ?></code></p><p>Сообщество: <code><?= h($b['community_id']) ?></code> · аккаунт: <code><?= h($b['account_id']) ?></code> · канал: <code><?= h($b['channel_id']) ?></code></p></section>
<?php if($botsManager&&(int)$b['active']): ?><section class="panel"><h2>Подготовить сообщение</h2><p>Для выпуска доступно одно неотменённое сообщение. Вводите только предназначенные для публикации сведения.</p><form method="post" class="formgrid"><?php formFields('bots.draft') ?><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><label>Выпуск<select name="release_id"><option value="">Без выпуска</option><?php foreach($botsReleases as $rel): ?><option value="<?= (int)$rel['id'] ?>" <?= $botsSelectedRelease&&(int)$botsSelectedRelease['id']===(int)$rel['id']?'selected':'' ?>><?= h($rel['tag']) ?></option><?php endforeach ?><?php if($botsSelectedRelease&&!in_array((int)$botsSelectedRelease['id'],array_map('intval',array_column($botsReleases,'id')),true)): ?><option selected value="<?= (int)$botsSelectedRelease['id'] ?>"><?= h($botsSelectedRelease['tag']) ?></option><?php endif ?></select></label><label>Запрос поддержки (вместо выпуска)<select name="support_id"><option value="">Без запроса</option><?php foreach($botsTickets as $ticket): ?><option value="<?= (int)$ticket['id'] ?>" <?= $botsTicket&&(int)$botsTicket['id']===(int)$ticket['id']?'selected':'' ?>>#<?= h($ticket['id']) ?> · <?= h($ticket['title']) ?> (<?= h($ticket['state']) ?>)</option><?php endforeach ?><?php if($botsTicket&&!in_array((int)$botsTicket['id'],array_map('intval',array_column($botsTickets,'id')),true)): ?><option selected value="<?= (int)$botsTicket['id'] ?>">#<?= h($botsTicket['id']) ?> · <?= h($botsTicket['title']) ?></option><?php endif ?></select></label><p>Текст вводится вручную: сведения обращения не копируются в публичный канал.</p><label>Сообщение<textarea name="message" rows="8" maxlength="2000" required><?= $botsSelectedRelease?h('Выпуск '.$botsSelectedRelease['tag']):'' ?></textarea></label><button class="primary">Сохранить предпросмотр</button></form></section><?php endif ?>
<section class="panel"><h2>Очередь ручной сверки</h2><p>Неопределённые, отказавшие и зависшие задания. Проверка выполняет только GET; отсутствие записи не доказывает недоставку.</p><?php if(!$botsQueue): ?><p>Нет записей в очереди.</p><?php endif ?><div class="tablewrap"><table><thead><tr><th>Сообщение</th><th>Состояние</th><th>Причина</th><th>Последний переход UTC</th></tr></thead><tbody><?php foreach(array_slice($botsQueue,0,50) as $q): ?><tr><td><a href="<?= h(url('bots',['project'=>$botsProject,'id'=>$q['id']])) ?>">#<?= h($q['id']) ?></a></td><td><?= h($q['state']) ?></td><td><?= h($q['reason']) ?></td><td><?= h(gmdate('Y-m-d H:i:s',(int)$q['state_at'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php if(count($botsQueue)>50): ?><a href="<?= h(url('bots',['project'=>$botsProject,'queue_before'=>$botsQueue[49]['id']])) ?>">Следующие записи очереди</a><?php endif ?></section>
<section class="panel"><h2>Обратная связь из выбранного канала</h2><p>Ручная регистрация сотрудником. Не является подтверждённым входящим событием API.</p><?php if($botsManager&&(int)$b['active']&&$botsServices): ?><form method="post" class="formgrid"><?php formFields('bots.feedback') ?><input type="hidden" name="project_id" value="<?= h($botsProject) ?>"><label>Сервис<select name="service_id" required><?php foreach($botsServices as $svc): ?><option value="<?= h($svc['id']) ?>"><?= h($svc['name']) ?></option><?php endforeach ?></select></label><label>ID сообщения в канале<input name="external_id" pattern="[1-9][0-9]{0,23}" maxlength="24" required></label><label>Получено (UTC)<input type="datetime-local" name="received_at" required value="<?= h(gmdate('Y-m-d\TH:i')) ?>"></label><label>Автор / источник<input name="requester" maxlength="180" required></label><label>Тема<input name="title" maxlength="180" required></label><label>Описание<textarea name="description" maxlength="4000" required></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> Проверил сообщение именно в указанном выше канале</label><button>Зарегистрировать запрос поддержки (MFA)</button></form><?php endif ?><?php foreach($botsFeedback as $f): ?><p><a href="<?= h(url('service_ops',['project'=>$botsProject,'service'=>$f['service_id']])) ?>">Запрос #<?= h($f['support_id']) ?> · <?= h($f['title']) ?></a> · ID канала <?= h($f['external_id']) ?> · <?= h($f['state']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$f['received_at'])) ?> UTC</p><?php endforeach ?></section>
<section class="panel"><h2>Сообщения</h2><?php if($botsTicket): ?><p>Запрос #<?= h($botsTicket['id']) ?> · <a href="<?= h(url('bots',['project'=>$botsProject])) ?>">Все сообщения</a></p><?php endif ?><div class="tablewrap"><table><thead><tr><th>ID</th><th>Выпуск / поддержка</th><th>Статус</th><th>UTC</th></tr></thead><tbody><?php foreach($botsMessages as $r): ?><tr><td><a href="<?= h(url('bots',['project'=>$botsProject,'id'=>$r['id']])) ?>">#<?= (int)$r['id'] ?></a></td><td><?php if($r['release_id']!==null): ?><a href="<?= h(url('releases',['project'=>$botsProject,'id'=>$r['release_id']])) ?>">#<?= (int)$r['release_id'] ?></a><?php elseif($r['support_id']!==null): ?><a href="<?= h(url('bots',['project'=>$botsProject,'support'=>$r['support_id']])) ?>">Запрос #<?= h($r['support_id']) ?></a><?php else: ?>—<?php endif ?></td><td><?= h($r['state']) ?></td><td><?= h(gmdate('Y-m-d H:i:s',(int)$r['created_at'])) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if($m): ?><section class="panel"><h2>Предпросмотр #<?= (int)$m['id'] ?> — <?= h($m['state']) ?></h2><p>Канал: <code><?= h($b['channel_id']) ?></code> · редакция аккаунта: <?= h($m['target_revision']) ?></p><?php if($botsSupport): ?><p><a href="<?= h(url('bots',['project'=>$botsProject,'support'=>$botsSupport['support_id']])) ?>">Запрос поддержки #<?= h($botsSupport['support_id']) ?></a> · редакция <?= h($botsSupport['support_version']) ?></p><?php endif ?><pre class="release-text"><?= h($m['message']) ?></pre><p>SHA-256 текста: <code><?= h($m['message_hash']) ?></code></p><p>Снимок подтверждения: <code><?= h($m['preview_hash']) ?></code></p><p>Удалённый ID: <code><?= h($m['remote_id']) ?></code> · попыток провайдера: <?= (int)$m['remote_attempts'] ?> · ID сообщения: <?= h($m['provider_message_id']??'—') ?> · <?= h($m['error_code']) ?></p>
<?php if($botsManager): $ops=[];$state=$m['state'];if($state==='draft'&&(int)$b['active'])$ops['confirm']='Подтвердить точный текст и канал';if(($state==='failed'&&$m['command']==='create'||$state==='retryable'&&(int)$m['remote_attempts']<8)&&(int)$b['active'])$ops['retry']='Повторить после отказа до отправки';if(in_array($state,['draft','failed','pending','retryable'],true)||$state==='queued'&&in_array($m['command'],['create','retry'],true))$ops['cancel']='Отменить до начала отправки';if(in_array($state,['pending','sending','retryable','uncertain'],true))$ops['check']='Сверить точный ID в Bots';if($state==='uncertain')$ops['close']='Закрыть без подтверждения доставки (без повтора)';foreach($ops as $op=>$title): ?><form method="post" class="inline"><?php formFields('bots.'.$op) ?><input type="hidden" name="project_id" value="<?= (int)$botsProject ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="preview_hash" value="<?= h($m['preview_hash']) ?>"><?php if($op==='close'): ?><input type="hidden" name="event_id" value="<?= h($botsLatestEvent) ?>"><label>Основание ручной сверки<input name="reason" maxlength="300" required></label><?php endif ?><label><input type="checkbox" name="confirm" value="yes" required> <?= h($title) ?></label><button class="secondary">Выполнить (MFA)</button></form><?php endforeach;endif ?>
<h3>История</h3><div class="tablewrap"><table><thead><tr><th>UTC</th><th>Состояние</th><th>Операция</th><th>Участник</th></tr></thead><tbody><?php foreach(array_slice($botsEvents,0,100) as $ev): ?><tr><td><?= h(gmdate('Y-m-d H:i:s',(int)$ev['created_at'])) ?></td><td><?= h($ev['state']) ?></td><td><?= h($ev['detail']) ?></td><td>#<?= (int)$ev['actor_id'] ?></td></tr><?php endforeach ?></tbody></table></div><?php if(count($botsEvents)>100): ?><a href="<?= h(url('bots',['project'=>$botsProject,'id'=>$m['id'],'event_before'=>$botsEvents[99]['id']])) ?>">Более ранние события</a><?php endif ?></section><?php endif ?>
<?php endif;endif ?>
